<?php
namespace App\Http\Controllers\Admin; use App\Domain\Clients\{ClientDependencyInspector,ClientManager,ClientRegistry,ClientRelationManager,ClientViewData}; use App\Domain\Installation\WebsiteSettings; use App\Http\Controllers\{Controller,PublicSiteController}; use App\Http\Requests\Clients\SaveClientRequest; use App\Models\{Capability,Client,Industry,Page,Product,Solution}; use Illuminate\Contracts\View\View; use Illuminate\Http\{RedirectResponse,Request,Response}; use Illuminate\Support\Carbon; use Illuminate\Validation\Rule; class ClientController extends Controller { public function index(Request $request):View{$f=$request->validate(['search'=>['nullable','string','max:160'],'type'=>['nullable',Rule::in(ClientRegistry::TYPES)],'industry'=>['nullable','integer'],'status'=>['nullable',Rule::in(['draft','published','scheduled','archived'])],'featured'=>['nullable','in:0,1'],'archived'=>['nullable','in:with,only,without']]);$q=Client::with('industry')->when($f['search']??null,fn($q,$v)=>$q->where(fn($q)=>$q->where('name','like',"%$v%")->orWhere('slug','like',"%$v%")))->when($f['type']??null,fn($q,$v)=>$q->where('client_type',$v))->when($f['industry']??null,fn($q,$v)=>$q->where('industry_id',$v))->when($f['status']??null,fn($q,$v)=>$q->where('status',$v))->when(isset($f['featured']),fn($q)=>$q->where('is_featured',(bool)$f['featured']));if(($f['archived']??'without')==='only')$q->whereNotNull('archived_at');elseif(($f['archived']??'without')==='without')$q->whereNull('archived_at');return view('admin.clients.index',['clients'=>$q->orderBy('display_order')->paginate(20)->withQueryString()]);} public function create():View{return $this->editor(new Client);} public function store(SaveClientRequest $request,ClientManager $manager):RedirectResponse{$item=$manager->save($request->validated(),null,$request->user()->id);return redirect()->route('admin.clients.edit',$item);} public function edit(Client $client):View{return $this->editor($client);} public function update(SaveClientRequest $request,Client $client,ClientManager $manager):RedirectResponse{$manager->save($request->validated(),$client,$request->user()->id);return back()->with('status','Client saved.');} private function editor(Client $item):View{if($item->exists)$item->load(['relatedSolutions','relatedProducts','relatedCapabilities','relatedPages']);return view('admin.clients.editor',['client'=>$item,'types'=>ClientRegistry::TYPES,'industries'=>Industry::whereNull('archived_at')->orderBy('title')->get(),'solutions'=>Solution::whereNull('archived_at')->limit(200)->get(),'products'=>Product::whereNull('archived_at')->limit(200)->get(),'capabilities'=>Capability::whereNull('archived_at')->limit(200)->get(),'pages'=>Page::whereNull('archived_at')->limit(200)->get(),'dependencies'=>$item->exists?app(ClientDependencyInspector::class)->inspect($item):null]);} public function publish(Client $client,ClientManager $m):RedirectResponse{$m->publish($client);return back();} public function schedule(Request $r,Client $client,ClientManager $m):RedirectResponse{$v=$r->validate(['scheduled_for'=>['required','date']]);$tz=app(WebsiteSettings::class)->current()?->timezone?:'UTC';$m->schedule($client,Carbon::parse($v['scheduled_for'],$tz)->utc()->toDateTimeString());return back();} public function unpublish(Client $client,ClientManager $m):RedirectResponse{$m->unpublish($client);return back();} public function archive(Client $client,ClientManager $m):RedirectResponse{$m->archive($client);return back();} public function restore(Client $client,ClientManager $m):RedirectResponse{$m->restore($client);return back();} public function duplicate(Request $r,Client $client,ClientManager $m):RedirectResponse{return redirect()->route('admin.clients.edit',$m->duplicate($client,$r->user()->id));} public function move(Client $client,string $direction,ClientManager $m):RedirectResponse{$m->move($client,$direction);return back();} public function relations(Request $r,Client $client,ClientRelationManager $m):RedirectResponse{$d=$r->validate(['solution_ids'=>['array','max:8'],'solution_ids.*'=>['integer','distinct','exists:solutions,id'],'product_ids'=>['array','max:8'],'product_ids.*'=>['integer','distinct','exists:products,id'],'capability_ids'=>['array','max:8'],'capability_ids.*'=>['integer','distinct','exists:capabilities,id'],'page_ids'=>['array','max:6'],'page_ids.*'=>['integer','distinct','exists:pages,id']]);$m->sync($client,$d['solution_ids']??[],$d['product_ids']??[],$d['capability_ids']??[],$d['page_ids']??[]);return back();} public function preview(Request $r,Client $client,ClientViewData $d):Response{return response()->view('clients.show',['client'=>$d->preview($client),'preview'=>true]+app(PublicSiteController::class)->sharedViewData($r))->header('Cache-Control','no-store, private, max-age=0')->header('X-Robots-Tag','noindex, nofollow');} }
